import{_ as l,o as t,c as i,b3 as o}from"./chunks/framework.VnelH-cX.js";const r="/docs-imgs/guide/SnowShot_2025-10-28_02-10-10.webp",c=JSON.parse('{"title":"翻译","description":"","frontmatter":{},"headers":[],"relativePath":"guide/function/translate.md","filePath":"guide/function/translate.md","lastUpdated":1786700458000}'),n={name:"guide/function/translate.md"};function e(s,a,h,g,d,p){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="翻译" tabindex="-1">翻译 <a class="header-anchor" href="#翻译" aria-label="Permalink to &quot;翻译&quot;">​</a></h1><p>Wing Shot 的翻译功能通过下载<strong>翻译</strong>插件开启，启动后将激活文本翻译的功能，如果同时下载了<strong>文本识别</strong>插件，还可以使用截图翻译等快捷功能。无论是日常学习、工作交流还是阅读外文资料，翻译功能都能为您提供便捷高效的语言转换服务。</p><p><img src="'+r+'" alt="翻译界面"></p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><p>打开 Wing Shot 界面，点击侧边栏菜单<strong>个性化</strong>下的<strong>插件</strong>打开插件管理页面。接着找到<strong>翻译</strong>插件，点击<strong>安装</strong>按钮即可完成翻译插件的安装。</p><h3 id="增强功能" tabindex="-1">增强功能 <a class="header-anchor" href="#增强功能" aria-label="Permalink to &quot;增强功能&quot;">​</a></h3><p>还可以继续安装<strong>文本识别</strong>插件，安装后它能和<strong>翻译</strong>插件配合，以此激活截图翻译、固定到屏幕翻译等更多实用功能。</p><h2 id="主要功能" tabindex="-1">主要功能 <a class="header-anchor" href="#主要功能" aria-label="Permalink to &quot;主要功能&quot;">​</a></h2><p>Wing Shot 的翻译功能为您提供了全方位的翻译体验：</p><ul><li><strong>多语言支持</strong>：支持多种语言之间的互译，包括中文、英语、日语、德语等</li><li><strong>多种翻译引擎</strong>：支持传统机器翻译和 AI 大模型翻译，可根据需求自由切换</li><li><strong>开箱即用</strong>：Wing Shot 默认提供了开箱可用的翻译服务，无需额外配置即可使用</li><li><strong>截图翻译</strong>：配合文本识别插件，可直接截取屏幕区域进行文字识别和翻译</li><li><strong>选中文本翻译</strong>：通过全局快捷键快速翻译系统中选中的任何文本</li></ul><h2 id="文本翻译" tabindex="-1">文本翻译 <a class="header-anchor" href="#文本翻译" aria-label="Permalink to &quot;文本翻译&quot;">​</a></h2><p>安装<strong>翻译</strong>插件后，侧边栏菜单<strong>工具栏</strong>下会自动增加<strong>翻译</strong>选项。点击菜单后即可进入翻译页面。</p><h3 id="基本使用" tabindex="-1">基本使用 <a class="header-anchor" href="#基本使用" aria-label="Permalink to &quot;基本使用&quot;">​</a></h3><p>在翻译页面，您可以：</p><ol><li><strong>输入文本</strong>：在输入框中直接输入或粘贴需要翻译的文本</li><li><strong>选择语言</strong>：选择源语言和目标语言（支持自动检测源语言）</li><li><strong>切换引擎</strong>：在多个翻译服务之间快速切换，对比翻译结果</li></ol><h3 id="翻译服务类型" tabindex="-1">翻译服务类型 <a class="header-anchor" href="#翻译服务类型" aria-label="Permalink to &quot;翻译服务类型&quot;">​</a></h3><p>Wing Shot 支持多种翻译服务类型：</p><ul><li><strong>传统机器翻译</strong>：快速响应，适合日常快速翻译需求</li><li><strong>AI 大模型翻译</strong>：配合 <strong>AI 对话</strong>插件使用，提供更准确、更符合上下文的翻译结果</li><li><strong>自定义 API</strong>：支持配置第三方翻译服务，满足专业翻译需求</li></ul><h3 id="翻译结果操作" tabindex="-1">翻译结果操作 <a class="header-anchor" href="#翻译结果操作" aria-label="Permalink to &quot;翻译结果操作&quot;">​</a></h3><p>翻译完成后，您可以对结果进行以下操作：</p><ul><li><strong>一键复制</strong>：快速复制翻译结果到剪贴板</li><li><strong>双向切换</strong>：点击切换按钮，将翻译结果作为源文本进行反向翻译</li></ul><h2 id="快捷功能" tabindex="-1">快捷功能 <a class="header-anchor" href="#快捷功能" aria-label="Permalink to &quot;快捷功能&quot;">​</a></h2><p>Wing Shot 提供了强大的翻译快捷功能，让您能够在任何场景下快速进行文本翻译。</p><h3 id="配置快捷键" tabindex="-1">配置快捷键 <a class="header-anchor" href="#配置快捷键" aria-label="Permalink to &quot;配置快捷键&quot;">​</a></h3><ol><li>在侧边栏点击<strong>快捷功能</strong>菜单</li><li>找到翻译相关的快捷键配置项：</li><li>点击按键录入按钮然后录制所需的组合快捷键</li><li>录入后点击确认后即可生效</li></ol><h3 id="快捷翻译场景" tabindex="-1">快捷翻译场景 <a class="header-anchor" href="#快捷翻译场景" aria-label="Permalink to &quot;快捷翻译场景&quot;">​</a></h3><p>配置快捷键后，您可以在以下场景快速进行翻译：</p><h4 id="截图翻译" tabindex="-1">截图翻译 <a class="header-anchor" href="#截图翻译" aria-label="Permalink to &quot;截图翻译&quot;">​</a></h4><p>需要先安装<strong>文本识别</strong>插件。</p><p>使用步骤：</p><ol><li>按下截图翻译快捷键</li><li>框选需要翻译的屏幕区域</li><li>点击<strong>文本识别翻译</strong>工具即可自动完成文本识别和翻译操作</li></ol><p>适用场景：</p><ul><li>翻译网页中的外文内容</li><li>阅读 PDF 文档中的外语段落</li><li>识别并翻译图片中的文字</li><li>翻译视频字幕或游戏文本</li></ul><h4 id="选中文本翻译" tabindex="-1">选中文本翻译 <a class="header-anchor" href="#选中文本翻译" aria-label="Permalink to &quot;选中文本翻译&quot;">​</a></h4><p>使用步骤：</p><ol><li>在任何应用中选中需要翻译的文本</li><li>按下选中文本翻译快捷键</li><li>自动弹出翻译结果窗口</li></ol><p>适用场景：</p><ul><li>快速翻译邮件或文档中的段落</li><li>阅读外文网页时即时翻译</li><li>学习时快速查看词句翻译</li><li>社交媒体上的多语言内容翻译</li></ul><h2 id="自定义翻译-api" tabindex="-1">自定义翻译 API <a class="header-anchor" href="#自定义翻译-api" aria-label="Permalink to &quot;自定义翻译 API&quot;">​</a></h2><p>如果您想使用自己的翻译 API 密钥或其他翻译服务提供商，Wing Shot 支持灵活的自定义配置。</p><h3 id="配置传统翻译-api" tabindex="-1">配置传统翻译 API <a class="header-anchor" href="#配置传统翻译-api" aria-label="Permalink to &quot;配置传统翻译 API&quot;">​</a></h3><p>配置步骤：</p><ol><li>在侧边栏点击<strong>设置</strong>下的<strong>功能设置</strong></li><li>找到<strong>翻译</strong>设置选项</li><li>点击添加 API 配置按钮，输入您的 API 配置信息</li><li>输入完毕后即可在翻译相关功能中使用新增的 API 配置</li></ol><h3 id="配置-ai-翻译服务" tabindex="-1">配置 AI 翻译服务 <a class="header-anchor" href="#配置-ai-翻译服务" aria-label="Permalink to &quot;配置 AI 翻译服务&quot;">​</a></h3><p>如果需要使用 AI 大模型进行翻译，则需要配置新增 AI 对话的 API 配置：</p><ol><li>在侧边栏点击<strong>设置</strong>下的<strong>功能设置</strong></li><li>找到<strong>AI 对话</strong>设置选项</li><li>添加您的 AI API 配置： <ul><li>API 地址</li><li>API 密钥</li><li>模型名称等参数</li></ul></li><li>配置完成后，在<strong>翻译</strong>中即可选择使用 AI 模型作为翻译引擎</li></ol>',46)])])}const b=l(n,[["render",e]]);export{c as __pageData,b as default};
